export function getVendorMeta(vendor?: string, model?: string): VendorPresetMeta {
  const mdl = (model || "").trim().toUpperCase();
  if (mdl.startsWith("MIPC") || mdl.includes("MERCURY")) {
    return VENDOR_PRESETS.find((v) => v.value === "mercury") || VENDOR_PRESETS[0];
  }
  const key = (vendor || "tplink").trim().toLowerCase();
  return VENDOR_PRESETS.find((v) => v.value === key) || VENDOR_PRESETS[0];
}

